func astNode(v any) *pegort.Node { n, _ := v.(*pegort.Node); return n }
func astIsNil(v any) bool        { n, ok := v.(*pegort.Node); return v == nil || ok && n == nil }

// astKid returns the value of element i of a tuple node's children (nil if there is none).
func astKid(kids []*pegort.Node, i int) any {
	if i < len(kids) {
		return pegort.UnboxNode(kids[i])
	}
	return nil
}

// The value of a rule, and a list element, holds an int, string or bool in a box.
func astInt(v any) int       { i, _ := pegort.UnboxValue(v).(int); return i }
func astString(v any) string { s, _ := pegort.UnboxValue(v).(string); return s }
func astBool(v any) bool     { x, _ := pegort.UnboxValue(v).(bool); return x }
func astPtrInt(v any) *int {
	if i, ok := pegort.UnboxValue(v).(int); ok {
		return &i
	}
	return nil
}
func astPtrString(v any) *string {
	if s, ok := pegort.UnboxValue(v).(string); ok {
		return &s
	}
	return nil
}
func astPtrBool(v any) *bool {
	if x, ok := pegort.UnboxValue(v).(bool); ok {
		return &x
	}
	return nil
}

// astChunk owns unused values and the next allocation size for one type.
// Handed-out values are never reused, even when a parse discards them.
type astChunk[T any] struct {
	free      []T
	next      int
	bootstrap uint8
}

// grow starts small and doubles up to limit. The request is always satisfied.
func (s *astChunk[T]) grow(n, initial, limit int) {
	size := s.next
	if size == 0 {
		size = initial
	}
	for size < n {
		size *= 2
	}
	s.free = make([]T, size)
	s.next = size * 2
	if s.next > limit {
		s.next = limit
	}
}

// astNew allocates the first three values independently so a later
// published value cannot retain discarded early siblings through a chunk.
// Later values use the original 8-to-256 chunk growth.
func astNew[T any](s *astChunk[T]) *T {
	if len(s.free) == 0 {
		if s.bootstrap < 3 {
			s.bootstrap++
			return new(T)
		}
		s.grow(1, 8, 256)
	}
	v := &s.free[0]
	s.free = s.free[1:]
	return v
}

// astSlice allocates the first nonempty small list independently to keep
// its backing values separate from later published lists of the same type.
func astSlice[T any](s *astChunk[T], n int) []T {
	if n == 0 {
		return []T{} // an empty list, not nil
	}
	if n > 256 {
		return make([]T, n)
	}
	if len(s.free) < n {
		if s.bootstrap == 0 {
			s.bootstrap = 1
			return make([]T, n)
		}
		s.grow(n, 64, 1024)
	}
	v := s.free[:n:n]
	s.free = s.free[n:]
	return v
}

// tinit sets up the typed rules (called at the end of init, after the rule tables).
func tinit() {
	tnamedPub := func(a any, x pegort.TVal) any {
		s, _ := a.(*tslabs)
		if s == nil {
			s = &tslabs{}
		}
		switch x.TName() {
		case "AttValue":
			return tv22(s, x)
		case "CDSect":
			return tv26(s, x)
		case "CharData":
			return tv24(s, x)
		case "CharRef":
			return tv28(s, x)
		case "Comment":
			return tv9(s, x)
		case "EncName":
			return tv4(s, x)
		case "EntityRef":
			return tv29(s, x)
		case "EntityValue":
			return tv20(s, x)
		case "Keyword":
			return tv17(s, x)
		case "Name":
			return tv30(s, x)
		case "Nmtoken":
			return tv32(s, x)
		case "Occurrence":
			return tv18(s, x)
		case "PERef":
			return tv12(s, x)
		case "PIData":
			return tv10(s, x)
		case "PubidLiteral":
			return tv16(s, x)
		case "SystemLiteral":
			return tv14(s, x)
		case "Version":
			return tv2(s, x)
		case "YesNo":
			return tv6(s, x)
		}
		return nil
	}
	for i, name := range []string{"AttValue", "CDSect", "CharData", "CharRef", "Comment", "EncName", "EntityRef", "EntityValue", "Keyword", "Name", "Nmtoken", "Occurrence", "PERef", "PIData", "PubidLiteral", "SystemLiteral", "Version", "YesNo"} {
		tnt[i+1] = pegort.TRegisterNodeType(name, tnamedPub)
	}
	trules[5].Nt = tnt[17]
	trules[7].Nt = tnt[6]
	trules[9].Nt = tnt[18]
	trules[12].Nt = tnt[5]
	trules[14].Nt = tnt[14]
	trules[18].Nt = tnt[13]
	trules[23].Nt = tnt[16]
	trules[24].Nt = tnt[16]
	trules[26].Nt = tnt[15]
	trules[27].Nt = tnt[15]
	trules[30].Nt = tnt[9]
	trules[31].Nt = tnt[9]
	trules[37].Nt = tnt[12]
	trules[40].Nt = tnt[9]
	trules[41].Nt = tnt[9]
	trules[43].Nt = tnt[9]
	trules[50].Nt = tnt[8]
	trules[51].Nt = tnt[8]
	trules[58].Nt = tnt[1]
	trules[59].Nt = tnt[1]
	trules[63].Nt = tnt[3]
	trules[65].Nt = tnt[2]
	trules[67].Nt = tnt[4]
	trules[68].Nt = tnt[7]
	trules[69].Nt = tnt[10]
	trules[71].Nt = tnt[11]
}

